        const statKey = quality === 'again' || quality === 'hard' ? 'hard' : (quality === 'good' ? 'medium' : 'easy');
        setSessionStats(prev => ({ ...prev, [statKey]: prev[statKey] + 1 }));

        // Next card setup
        setIsFlipped(false);
        setTimeout(() => {
          setCurrentIndex(prev => prev + 1);
        }, 150); // slight delay for smooth transition
      }
