            <div className="flashcard-label">C├óu hß╗Åi</div>
            <div className="flashcard-content">{currentCard.question}</div>
            <p style={{ marginTop: 'auto', fontSize: '14px', opacity: 0.5 }}>Click ─æß╗â lß║¡t thß║╗</p>
