              <span style={{ display: 'block', fontSize: '18px', fontWeight: 'bold' }}>1m</span>
              Lß║íi (Again)
            </button>
            <button className="btn-warning" onClick={() => handleLevelChoice('hard')} style={{ flex: 1 }}>
              <span style={{ display: 'block', fontSize: '18px', fontWeight: 'bold' }}>Sß╗¢m</span>
